// Render capabilities.json as a human-readable Docusaurus page.
//
//   capabilities.json → website/docs/status.md
//
// Run at build time (via website's sync-docs) so the page can never drift
// from the JSON. Idempotent and deterministic: run it any number of times,
// output depends only on capabilities.json. Pure Node, no dependencies.
// The generated file carries a DO-NOT-EDIT banner; edit the JSON instead.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(ROOT, 'capabilities.json');
const TARGET = join(ROOT, 'website', 'docs', 'status.md');

// Markdown table cells: backslashes first, then the pipe delimiter.
function cell(s) {
	return String(s).replace(/\\/g, '\\\\').replace(/\|/g, '\\|');
}

function yaml(s) {
	return `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

const json = JSON.parse(readFileSync(SOURCE, 'utf8'));

const rows = (json.consumers ?? []).map((c) => {
	const rw = `${c.read ? 'R' : ''}${c.write ? 'W' : ''}`.split('').join(' + ') || '—';
	const dep = c.dependency?.type ?? '—';
	const conf = c.conformanceLevel ?? 'not audited';
	const date = c.evidenceDate ?? json.lastAudited;
	return {
		id: c.id,
		row: `| ${cell(c.id)} | ${cell(c.pkg)} | ${cell(rw)} | ${cell(dep)} | ${cell(conf)} | ${cell(date)} |`,
		notes: c.conformanceNotes ?? null,
	};
});

const out = `---
id: ${yaml('status')}
slug: ${yaml('status')}
title: ${yaml('Ecosystem status')}
description: ${yaml('Live status of every .curt consumer, rendered from the machine-readable capabilities tracker at build time.')}
---

<!-- GENERATED by scripts/gen-status-page.mjs from capabilities.json — DO NOT EDIT. Edit capabilities.json and re-run the script (npm run sync-docs in website/). -->

# Ecosystem status

Rendered from [\`capabilities.json\`](https://github.com/JordanNewell/dot_curt/blob/main/capabilities.json) — the single source of truth, regenerated on every site build. Last audit ${cell(json.lastAudited)}; tracker format version ${cell(json.formatVersion)}; spec revision ${cell(json.specRevision)}. Reference conformance: ${cell(json.reference?.conformanceLevel ?? '—')}.

## Consumers (${json.consumers?.length ?? 0})

| Consumer | Pkg | R/W | Dependency | Conformance | Evidence date |
|---|---|---|---|---|---|
${rows.map((r) => r.row).join('\n')}

Entries without an explicit \`evidenceDate\` predate that field; their evidence date is the tracker's \`lastAudited\` date.

## Conformance notes

${rows
	.filter((r) => r.notes)
	.map((r) => `- **${cell(r.id)}** — ${r.notes}`)
	.join('\n')}

## Out of ecosystem (${json.outOfEcosystem?.length ?? 0})

No \`.curt\` references; one grep to confirm still-out.

${(json.outOfEcosystem ?? []).map((o) => `- **${cell(o.repo)}** — ${cell(o.note)}`).join('\n')}

## Ecosystem findings

${(json.ecosystemFindings ?? []).map((f) => `- ${f}`).join('\n')}
`;

writeFileSync(TARGET, out);
console.log(`generated ${TARGET.replace(ROOT + '\\', '').replace(ROOT + '/', '')} from capabilities.json`);
console.log('done.');
